144	std::string HttpRequest::createRequest()
145	{
146	  authConfig_ = authConfigFactory_->createAuthConfig(request_, option_);
147	  auto requestLine = request_->getMethod();
148	  requestLine += ' ';
149	  if (proxyRequest_) {
150	    if (getProtocol() == "ftp" && request_->getUsername().empty() &&
151	        authConfig_) {
152	      // Insert user into URI, like ftp://USER@host/
153	      auto uri = getCurrentURI();
154	      assert(uri.size() >= 6);
155	      uri.insert(6, util::percentEncode(authConfig_->getUser()) + '@');
156	      requestLine += uri;
157	    }
158	    else {
159	      requestLine += getCurrentURI();
160	    }
161	  }
162	  else {
163	    requestLine += getDir();
164	    requestLine += getFile();
165	    requestLine += getQuery();
166	  }
167	  requestLine += " HTTP/1.1\r\n";
168	
169	  std::vector<std::pair<std::string, std::string>> builtinHds;
170	  builtinHds.reserve(20);
171	  builtinHds.emplace_back("User-Agent:", userAgent_);
172	  std::string acceptTypes = "*/*";
173	  if (acceptMetalink_) {
174	    // The mime types of Metalink are used for "transparent metalink".
175	    const auto metalinkTypes = getMetalinkContentTypes();
176	    for (size_t i = 0; metalinkTypes[i]; ++i) {
177	      acceptTypes += ',';
178	      acceptTypes += metalinkTypes[i];
179	    }
180	  }
181	  builtinHds.emplace_back("Accept:", acceptTypes);
182	  if (contentEncodingEnabled_) {
183	    std::string acceptableEncodings;
184	#ifdef HAVE_ZLIB
185	    if (acceptGzip_) {
186	      acceptableEncodings += "deflate, gzip";
187	    }
188	#endif // HAVE_ZLIB
189	    if (!acceptableEncodings.empty()) {
190	      builtinHds.emplace_back("Accept-Encoding:", acceptableEncodings);
191	    }
192	  }
193	  builtinHds.emplace_back("Host:", getHostText(getURIHost(), getPort()));
194	  if (noCache_) {
195	    builtinHds.emplace_back("Pragma:", "no-cache");
196	    builtinHds.emplace_back("Cache-Control:", "no-cache");
197	  }
198	  if (!request_->isKeepAliveEnabled() && !request_->isPipeliningEnabled()) {
199	    builtinHds.emplace_back("Connection:", "close");
200	  }
201	  if (segment_ && segment_->getLength() > 0 &&
202	      (request_->isPipeliningEnabled() || getStartByte() > 0 ||
203	       getEndByte() > 0)) {
204	    std::string rangeHeader = "bytes=";
205	    rangeHeader += util::uitos(getStartByte());
206	    rangeHeader += '-';
207	
208	    if (request_->isPipeliningEnabled() || getEndByte() > 0) {
209	      // FTP via http proxy does not support endbytes, but in that
210	      // case, request_->isPipeliningEnabled() is false and
211	      // getEndByte() is 0.
212	      rangeHeader += util::itos(getEndByte());
213	    }
214	    builtinHds.emplace_back("Range:", rangeHeader);
215	  }
216	  if (proxyRequest_) {
217	    if (request_->isKeepAliveEnabled() || request_->isPipeliningEnabled()) {
218	      builtinHds.emplace_back("Connection:", "Keep-Alive");
219	    }
220	  }
221	  if (proxyRequest_ && !proxyRequest_->getUsername().empty()) {
222	    builtinHds.push_back(getProxyAuthString());
223	  }
224	  if (authConfig_) {
225	    auto authText = authConfig_->getAuthText();
226	    std::string val = "Basic ";
227	    val += base64::encode(std::begin(authText), std::end(authText));
228	    builtinHds.emplace_back("Authorization:", val);
229	  }
230	  if (!request_->getReferer().empty()) {
231	    builtinHds.emplace_back("Referer:", request_->getReferer());
232	  }
233	  if (cookieStorage_) {
234	    std::string cookiesValue;
235	    auto path = getDir();
236	    path += getFile();
237	    auto cookies = cookieStorage_->criteriaFind(
238	        getHost(), path, Time().getTimeFromEpoch(), getProtocol() == "https");
239	    for (auto c : cookies) {
240	      cookiesValue += c->toString();
241	      cookiesValue += ';';
242	    }
243	    if (!cookiesValue.empty()) {
244	      builtinHds.emplace_back("Cookie:", cookiesValue);
245	    }
246	  }
247	  if (!ifModSinceHeader_.empty()) {
248	    builtinHds.emplace_back("If-Modified-Since:", ifModSinceHeader_);
249	  }
250	  if (!noWantDigest_) {
251	    // Send Want-Digest header field with only limited hash algorithms:
252	    // SHA-512, SHA-256, and SHA-1.
253	    std::string wantDigest;
254	    if (MessageDigest::supports("sha-512")) {
255	      wantDigest += "SHA-512;q=1, ";
256	    }
257	    if (MessageDigest::supports("sha-256")) {
258	      wantDigest += "SHA-256;q=1, ";
259	    }
260	    if (MessageDigest::supports("sha-1")) {
261	      wantDigest += "SHA;q=0.1, ";
262	    }
263	    if (!wantDigest.empty()) {
264	      wantDigest.erase(wantDigest.size() - 2);
265	      builtinHds.emplace_back("Want-Digest:", wantDigest);
266	    }
267	  }
268	  for (const auto& builtinHd : builtinHds) {
269	    auto it = std::find_if(std::begin(headers_), std::end(headers_),
270	                           [&builtinHd](const std::string& hd) {
271	                             return util::istartsWith(hd, builtinHd.first);
272	                           });
273	    if (it == std::end(headers_)) {
274	      requestLine += builtinHd.first;
275	      requestLine += ' ';
276	      requestLine += builtinHd.second;
277	      requestLine += "\r\n";
278	    }
279	  }
280	  // append additional headers given by user.
281	  for (const auto& hd : headers_) {
282	    requestLine += hd;
283	    requestLine += "\r\n";
284	  }
285	  requestLine += "\r\n";
286	  return requestLine;
287	}
