72	std::string removeFragment(const std::string& uri)
73	{
74	  std::string::size_type sharpIndex = uri.find("#");
75	  if (sharpIndex == std::string::npos) {
76	    return uri;
77	  }
78	  else {
79	    return uri.substr(0, sharpIndex);
80	  }
