103	bool Request::redirectUri(const std::string& uri)
104	{
105	  supportsPersistentConnection_ = true;
106	  ++redirectCount_;
107	  if (uri.empty()) {
108	    return false;
109	  }
110	  std::string redirectedUri;
111	  if (util::startsWith(uri, "//")) {
112	    // Network-path reference (according to RFC 3986, Section 4.2)
113	    // Just complement current protocol.
114	    redirectedUri = getProtocol();
115	    redirectedUri += ":";
116	    redirectedUri += uri;
117	  }
118	  else {
119	    std::string::size_type schemeEnd = uri.find("://");
120	    bool absUri;
121	    if (schemeEnd == std::string::npos) {
122	      absUri = false;
123	    }
124	    else {
125	      absUri = true;
126	      // Check that scheme is acceptable one.
127	      for (size_t i = 0; i < schemeEnd; ++i) {
128	        char c = uri[i];
129	        if (!util::isAlpha(c) && !util::isDigit(c) && c != '+' && c != '-' &&
130	            c != '.') {
131	          absUri = false;
132	          break;
133	        }
134	      }
135	    }
136	    if (absUri) {
137	      redirectedUri = uri;
138	    }
139	    else {
140	      // rfc2616 requires absolute URI should be provided by Location header
141	      // field, but some servers don't obey this rule.
142	      // UPDATE: draft-ietf-httpbis-p2-semantics-18 now allows this.
143	      redirectedUri = uri::joinUri(currentUri_, uri);
144	    }
145	  }
146	  return parseUri(redirectedUri);
147	}
