71	void HttpResponse::validateResponse() const
72	{
73	  int statusCode = getStatusCode();
74	  switch (statusCode) {
75	  case 200: // OK
76	  case 206: // Partial Content
77	    if (!httpHeader_->defined(HttpHeader::TRANSFER_ENCODING)) {
78	      // compare the received range against the requested range
79	      auto responseRange = httpHeader_->getRange();
80	      if (!httpRequest_->isRangeSatisfied(responseRange)) {
81	        throw DL_ABORT_EX2(
82	            fmt(EX_INVALID_RANGE_HEADER, httpRequest_->getStartByte(),
83	                httpRequest_->getEndByte(), httpRequest_->getEntityLength(),
84	                responseRange.startByte, responseRange.endByte,
85	                responseRange.entityLength),
86	            error_code::CANNOT_RESUME);
87	      }
88	    }
89	    return;
90	  case 304: // Not Modified
91	    if (!httpRequest_->conditionalRequest()) {
92	      throw DL_ABORT_EX2("Got 304 without If-Modified-Since or If-None-Match",
93	                         error_code::HTTP_PROTOCOL_ERROR);
94	    }
95	    return;
96	  case 300: // Multiple Choices
97	  case 301: // Moved Permanently
98	  case 302: // Found
99	  case 303: // See Other
100	  case 307: // Temporary Redirect
101	  case 308: // Permanent Redirect
102	    if (!httpHeader_->defined(HttpHeader::LOCATION)) {
103	      throw DL_ABORT_EX2(fmt(EX_LOCATION_HEADER_REQUIRED, statusCode),
104	                         error_code::HTTP_PROTOCOL_ERROR);
105	    }
106	    return;
107	  }
108	  if (statusCode >= 400) {
109	    return;
110	  }
111	  throw DL_ABORT_EX2(fmt("Unexpected status %d", statusCode),
112	                     error_code::HTTP_PROTOCOL_ERROR);
113	}
