283	bool parseMetalinkHttpLink(MetalinkHttpEntry& result, const std::string& s)
284	{
285	  const auto first = std::find(s.begin(), s.end(), '<');
286	  if (first == s.end()) {
287	    return false;
288	  }
289	
290	  auto last = std::find(first, s.end(), '>');
291	  if (last == s.end()) {
292	    return false;
293	  }
294	
295	  auto p = util::stripIter(first + 1, last);
296	  if (p.first == p.second) {
297	    return false;
298	  }
299	
300	  result.uri.assign(p.first, p.second);
301	  last = std::find(last, s.end(), ';');
302	  if (last != s.end()) {
303	    ++last;
304	  }
305	  bool ok = false;
306	  while (1) {
307	    std::string name, value;
308	    auto r = util::nextParam(name, value, last, s.end(), ';');
309	    last = r.first;
310	
311	    if (!r.second) {
312	      break;
313	    }
314	
315	    if (value.empty()) {
316	      if (name == "pref") {
317	        result.pref = true;
318	      }
319	      continue;
320	    }
321	
322	    if (name == "rel") {
323	      if (value == "duplicate") {
324	        ok = true;
325	      }
326	      else {
327	        ok = false;
328	      }
329	      continue;
330	    }
331	
332	    if (name == "pri") {
333	      int32_t priValue;
334	      if (util::parseIntNoThrow(priValue, value)) {
335	        if (1 <= priValue && priValue <= 999999) {
336	          result.pri = priValue;
337	        }
338	      }
339	      continue;
340	    }
341	
342	    if (name == "geo") {
343	      util::lowercase(value);
344	      result.geo = value;
345	      continue;
346	    }
347	  }
348	  return ok;
349	}
350	
351	} // namespace
352	
353	// Metalink/HTTP is defined by http://tools.ietf.org/html/rfc6249.
354	// Link header field is defined by http://tools.ietf.org/html/rfc5988.
355	void HttpResponse::getMetalinKHttpEntries(
356	    std::vector<MetalinkHttpEntry>& result,
357	    const std::shared_ptr<Option>& option) const
358	{
359	  auto p = httpHeader_->equalRange(HttpHeader::LINK);
360	  for (; p.first != p.second; ++p.first) {
361	    MetalinkHttpEntry e;
362	    if (parseMetalinkHttpLink(e, (*p.first).second)) {
363	      result.push_back(e);
364	    }
365	  }
366	
367	  if (!result.empty()) {
368	    std::vector<std::string> locs;
369	    if (option->defined(PREF_METALINK_LOCATION)) {
370	      const std::string& loc = option->get(PREF_METALINK_LOCATION);
371	      util::split(loc.begin(), loc.end(), std::back_inserter(locs), ',', true);
372	      for (auto& l : locs) {
373	        util::lowercase(l);
374	      }
375	    }
376	    for (auto& r : result) {
377	      if (std::find(locs.begin(), locs.end(), r.geo) != locs.end()) {
378	        r.pri -= 999999;
379	      }
380	    }
381	  }
382	
383	  std::sort(result.begin(), result.end());
384	}
385	
386	// Digest header field is defined by
387	// http://tools.ietf.org/html/rfc3230.
388	void HttpResponse::getDigest(std::vector<Checksum>& result) const
389	{
390	  auto p = httpHeader_->equalRange(HttpHeader::DIGEST);
391	  for (; p.first != p.second; ++p.first) {
392	    const std::string& s = (*p.first).second;
393	    std::string::const_iterator itr = s.begin();
394	    while (1) {
395	      std::string hashType, digest;
396	      auto r = util::nextParam(hashType, digest, itr, s.end(), ',');
397	      itr = r.first;
398	      if (!r.second) {
399	        break;
400	      }
401	
402	      util::lowercase(hashType);
403	      digest = base64::decode(digest.begin(), digest.end());
404	      if (!MessageDigest::supports(hashType) ||
405	          MessageDigest::getDigestLength(hashType) != digest.size()) {
406	        continue;
407	      }
408	
409	      result.push_back(Checksum(hashType, digest));
410	    }
411	  }
412	
413	  std::sort(result.begin(), result.end(), HashTypeStronger());
414	  std::vector<Checksum> temp;
415	  for (auto i = result.begin(), eoi = result.end(); i != eoi;) {
416	    bool ok = true;
417	    auto j = i + 1;
418	    for (; j != eoi; ++j) {
419	      if ((*i).getHashType() != (*j).getHashType()) {
420	        break;
421	      }
422	
423	      if ((*i).getDigest() != (*j).getDigest()) {
424	        ok = false;
425	      }
426	    }
427	
428	    if (ok) {
429	      temp.push_back(*i);
430	    }
431	    i = j;
432	  }
433	  std::swap(temp, result);
434	}
