336	bool HttpResponseCommand::shouldInflateContentEncoding(
337	    HttpResponse* httpResponse)
338	{
339	  // Basically, on the fly inflation cannot be made with segment
340	  // download, because in each segment we don't know where the date
341	  // should be written.  So turn off segmented downloading.
342	  // Meanwhile, Some server returns content-encoding: gzip for .tgz
343	  // files.  I think those files should not be inflated by clients,
344	  // because it is the original format of those files. Current
345	  // implementation just inflates these files nonetheless.
346	  const std::string& ce = httpResponse->getContentEncoding();
347	  return httpResponse->getHttpRequest()->acceptGZip() &&
348	         (ce == "gzip" || ce == "deflate");
